KG42.register("rules-e6802fc116243cdfef5b2280",{"id":"01-central_pool::v141-c-R005","paper":"01-central_pool","record":{"rule_id":"v141-c-R005","mechanism_id":"v141-a-M01","name":"Local clearing price","process_stage":"pricing","market_meaning":"Local market clearing determines the community prices alongside the executed quantities. Scope: Lower-level community microgrid market clearing in the proposed bilevel framework. The social-welfare maximization approach determines local prices within the marginal-pricing framework. Scope: Price formation in the community microgrid internal local market. An entity executing a positive community export has a local price equal to the community energy-balance dual value minus the unitary operator fee. Two entities exporting to the community at that time have equal local prices. Scope: Executed community exports at the lower-level optimum, for each entity and time period. Condition: The entity exports a strictly positive energy quantity to the community at the relevant time. An entity executing a positive community import has a local price equal to the community energy-balance dual value plus the unitary operator fee. Scope: Executed community imports at the lower-level optimum, for each entity and time period. Condition: The entity imports a strictly positive energy quantity from the community at the relevant time. The buyer's local price includes the operator's transaction fee, collected on both sides of the exchange, in addition to the seller's local price. Scope: The two-entity, one-period example in which entity 1 buys local energy from entity 2. Condition: The operator collects its transaction fee on both the community import and export. The local price at which an entity exchanges energy with the community is the dual variable of that entity's energy-balance constraint (11). Scope: Entity-specific community energy prices at each time period in the proposed marginal-pricing formulation. Each local price is bounded below by the community energy-balance dual value minus the unitary operator fee and above by that dual value plus the fee. Scope: Local prices for each entity and time period in the lower-level dual formulation. Condition: The lower-level dual constraints are satisfied.","independence_rationale":"Relations governed by the approved function pricing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.local","clearing.social_welfare","execution.energy_trade","pricing.local","settlement.payment"],"E":[{"edge_id":"v141-c-R005-E001","source":"clearing.local","target":"pricing.local","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-e011"]},{"edge_id":"v141-c-R005-E002","source":"clearing.social_welfare","target":"pricing.local","type":"links","constraint_ids":["v141-c-R005-C002"],"evidence_ids":["v141-b-g01-e003"]},{"edge_id":"v141-c-R005-E003","source":"pricing.local","target":"execution.energy_trade","type":"conditional_on","constraint_ids":["v141-c-R005-C003","v141-c-R005-C004"],"evidence_ids":["v141-b-g01-e029","v141-b-g03-e07","v141-b-g03-e29"]},{"edge_id":"v141-c-R005-E004","source":"settlement.payment","target":"pricing.local","type":"links","constraint_ids":["v141-c-R005-C005"],"evidence_ids":["v141-b-g02-E33"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Entity-specific community energy prices at each time period in the proposed marginal-pricing formulation. | Executed community exports at the lower-level optimum, for each entity and time period. | Executed community imports at the lower-level optimum, for each entity and time period. | Local prices for each entity and time period in the lower-level dual formulation. | Lower-level community microgrid market clearing in the proposed bilevel framework. | Price formation in the community microgrid internal local market. | The two-entity, one-period example in which entity 1 buys local energy from entity 2.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e011","v141-b-g01-e025","v141-b-g01-e028","v141-b-g01-e029","v141-b-g02-E33","v141-b-g03-e07","v141-b-g03-e29","v141-b-g04-E05"]},"x":[{"variable_id":"v141-c-R005-x-pi_com","symbol":"\\pi_{u,t}^{com}","meaning":"Community market price at which entity u exchanges energy with the community at time t; it is the dual variable of entity u's energy-balance constraint (11).","kind":"operational","domain":"\\mathbb{R}","unit":"€/kWh","indices":["u","t"],"evidence_ids":["v141-b-g01-e025","v141-b-g01-e029","v141-b-g03-e29","v141-b-g04-E05"]},{"variable_id":"v141-c-R005-x-e_com","symbol":"e_{u,t}^{com}","meaning":"Energy exported to the community at time period t by entity u.","kind":"operational","domain":"\\mathbb{R}_+","unit":"kWh","indices":["u","t"],"evidence_ids":["v141-b-g01-e029","v141-b-g03-e29","v141-b-g03-e07"]},{"variable_id":"v141-c-R005-x-i_com","symbol":"i_{u,t}^{com}","meaning":"Energy imported from the community at time period t by entity u.","kind":"operational","domain":"\\mathbb{R}_+","unit":"kWh","indices":["u","t"],"evidence_ids":["v141-b-g01-e029","v141-b-g03-e29"]},{"variable_id":"v141-c-R005-x-mu","symbol":"\\mu_t","meaning":"Dual variable of the community energy-balance constraint (12), endogenous to the lower-level clearing and entering the local-price relations; unit follows the price interpretation (€/kWh in the source examples).","kind":"operational","domain":"\\mathbb{R}","unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-e029","v141-b-g01-e022","v141-b-g03-e23","v141-b-g03-e29"]}],"theta":[{"parameter_id":"v141-c-R005-theta-gamma_com","symbol":"\\gamma^{com}","meaning":"Unitary fee of the community microgrid operator, collected on community exchanges and embedded in the local prices.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"€/kWh","indices":[],"evidence_ids":["v141-b-g01-e028","v141-b-g01-e007","v141-b-g03-e29"]}],"phi":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"Local market clearing determines the community prices alongside the executed quantities. Scope: Lower-level community microgrid market clearing in the proposed bilevel framework.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e011"]},{"constraint_id":"v141-c-R005-C002","kind":"procedural","role":"core","statement":"The social-welfare maximization approach determines local prices within the marginal-pricing framework. Scope: Price formation in the community microgrid internal local market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.social_welfare","pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e003"]},{"constraint_id":"v141-c-R005-C003","kind":"logical","role":"core","statement":"An entity executing a positive community export has a local price equal to the community energy-balance dual value minus the unitary operator fee. Two entities exporting to the community at that time have equal local prices. Scope: Executed community exports at the lower-level optimum, for each entity and time period. Condition: The entity exports a strictly positive energy quantity to the community at the relevant time.","expression":"\\forall u \\in \\mathcal{U}, \\forall t \\in \\mathcal{T}: \\left( e_{u,t}^{com} > 0 \\Rightarrow \\pi_{u,t}^{com} = \\mu_t - \\gamma^{com} \\right) \\wedge \\forall u,v \\in \\mathcal{U}, \\forall t \\in \\mathcal{T}: \\left( e_{u,t}^{com} > 0 \\wedge e_{v,t}^{com} > 0 \\Rightarrow \\pi_{u,t}^{com} = \\pi_{v,t}^{com} \\right)","formalization_origin":"source","template_id":null,"members":["pricing.local","execution.energy_trade"],"variable_refs":["v141-c-R005-x-pi_com","v141-c-R005-x-e_com","v141-c-R005-x-mu"],"parameter_refs":["v141-c-R005-theta-gamma_com"],"evidence_ids":["v141-b-g01-e029","v141-b-g03-e07","v141-b-g03-e29","v141-b-g04-E05"]},{"constraint_id":"v141-c-R005-C004","kind":"logical","role":"core","statement":"An entity executing a positive community import has a local price equal to the community energy-balance dual value plus the unitary operator fee. Scope: Executed community imports at the lower-level optimum, for each entity and time period. Condition: The entity imports a strictly positive energy quantity from the community at the relevant time.","expression":"\\forall u \\in \\mathcal{U}, \\forall t \\in \\mathcal{T}: \\left( i_{u,t}^{com} > 0 \\Rightarrow \\pi_{u,t}^{com} = \\mu_t + \\gamma^{com} \\right)","formalization_origin":"source","template_id":null,"members":["pricing.local","execution.energy_trade"],"variable_refs":["v141-c-R005-x-pi_com","v141-c-R005-x-i_com","v141-c-R005-x-mu"],"parameter_refs":["v141-c-R005-theta-gamma_com"],"evidence_ids":["v141-b-g01-e029","v141-b-g03-e29","v141-b-g04-E05"]},{"constraint_id":"v141-c-R005-C005","kind":"procedural","role":"core","statement":"The buyer's local price includes the operator's transaction fee, collected on both sides of the exchange, in addition to the seller's local price. Scope: The two-entity, one-period example in which entity 1 buys local energy from entity 2. Condition: The operator collects its transaction fee on both the community import and export.","expression":"\\forall u,u' \\in \\mathcal{U}, \\forall t \\in \\mathcal{T}: \\left( e_{u,t}^{com} > 0 \\wedge i_{u',t}^{com} > 0 \\Rightarrow \\pi_{u',t}^{com} = \\pi_{u,t}^{com} + 2\\gamma^{com} \\right)","formalization_origin":"source","template_id":null,"members":["settlement.payment","pricing.local"],"variable_refs":["v141-c-R005-x-pi_com","v141-c-R005-x-e_com","v141-c-R005-x-i_com"],"parameter_refs":["v141-c-R005-theta-gamma_com"],"evidence_ids":["v141-b-g02-E33","v141-b-g03-e01","v141-b-g03-e29"]},{"constraint_id":"v141-c-R005-C006","kind":"procedural","role":"core","statement":"The local price at which an entity exchanges energy with the community is the dual variable of that entity's energy-balance constraint (11). Scope: Entity-specific community energy prices at each time period in the proposed marginal-pricing formulation.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R005-x-pi_com"],"parameter_refs":[],"evidence_ids":["v141-b-g01-e025"]},{"constraint_id":"v141-c-R005-C007","kind":"procedural","role":"core","statement":"Each local price is bounded below by the community energy-balance dual value minus the unitary operator fee and above by that dual value plus the fee. Scope: Local prices for each entity and time period in the lower-level dual formulation. Condition: The lower-level dual constraints are satisfied.","expression":"\\forall u \\in \\mathcal{U}, \\forall t \\in \\mathcal{T}: \\mu_t - \\gamma^{com} \\leq \\pi_{u,t}^{com} \\leq \\mu_t + \\gamma^{com}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R005-x-pi_com","v141-c-R005-x-mu"],"parameter_refs":["v141-c-R005-theta-gamma_com"],"evidence_ids":["v141-b-g01-e028","v141-b-g01-e029","v141-b-g04-E05","v141-b-g03-e23"]}],"pi":[{"evidence_id":"v141-b-g01-e003","location":{"location_id":"src-13c261d954-p03-c2r2__v141-a-M01-participation","page":3,"printed_page":null,"section":"1.2. Paper contribution","anchor_text":"( g , p y p g g y , n- storage services). ol is 1.2. Paper contribution s- de The aim of this paper ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Summarizing, the main novelties of this paper in the context of community microgrids, are the following:\n• the design of a local market for community microgrids, where the prices are determined through a social welfare maximization approach fulfilling the marginal pricing framework;\n• the introduction of a Pareto superior-type criterion to guarantee non-penalizing conditions for the entities in the community, thus stimulating participation on a voluntary basis;\n• the proposal of a benevolent planner operating the community, who fairly shares the profits of the community among the entities based on non-discriminatory rules;\n• the possibility to appraise different services used by the community, such as the storage and the community microgrid operator."},{"evidence_id":"v141-b-g01-e011","location":{"location_id":"src-13c261d954-p04-c2r3__v141-a-M01-clearing","page":4,"printed_page":null,"section":"3.1. The bilevel model","anchor_text":"th level objective functions are different, and represent conflicting inter- n- ests. Conversely, in","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Conversely, in power system economics [29-32], bilevel programming is typically used to access dual variables, which represent market prices within the marginal pricing framework [21]. This is the main reason to adopt a bilevel formulation in this paper. In the proposed bilevel model, the lower level solves the community microgrid market clearing problem, by determining: the executed quantities, the community prices, the community symmetric reserve, and the community peak power, with the aim of maximizing the social welfare of the community."},{"evidence_id":"v141-b-g01-e025","location":{"location_id":"src-13c261d954-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":"3.1.1. Lower level problem","anchor_text":"( i ugri, t e ugri, t )/ T p t . t peak 0 u (15) Constraint (11) defines the energy balance for each","equation_id":"(11)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"It is stressed that the dual variable $\\pi_{u,t}^{com}$ of constraint (11) has an important economic interpretation within the marginal pricing framework [21,22]. Indeed, being $\\pi_{u,t}^{com}$ the dual variable of the energy balance constraint for entity u, in the proposed formulation it represents the market price at which entity u exchanges energy with the community at time t [33]."},{"evidence_id":"v141-b-g01-e028","location":{"location_id":"src-13c261d954-p02-c1r3__v141-a-M01-clearing","page":2,"printed_page":null,"section":"Nomenclature","anchor_text":"d t,l p p p , s d she, kW rd Eucapt, maximum power export to the grid at time period t, with u , kW ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"Parameters\n$C_{d,t}^{nfl}$ non-flexible power consumption at time period t, with $d \\in \\mathcal{D}^{nfl}$, kW\n$C_{d,t}^{she}$ flexible power consumption at time period t, with $d \\in \\mathcal{D}^{she}$, kW\n$E_{u,t}^{cap}$ maximum power export to the grid at time period t, with $u \\in \\mathcal{U}$, kW\n$I_{u,t}^{cap}$ maximum power import from the grid at time period t, with $u \\in \\mathcal{U}$, kW\n$P_{d,t}^{nst}$ non-steerable power generation at time period t, with $d \\in \\mathcal{D}^{nst}$, kW\n$P_{d,t}^{ste}$ steerable power generation at time period t, with $d \\in \\mathcal{D}^{ste}$, kW\n$\\bar{P}_d$ maximum charging power of battery d, with $d \\in \\mathcal{D}^{sto}$, kW\n$\\underline{P}_d$ maximum discharging power of battery d, with $d \\in \\mathcal{D}^{sto}$, kW\n$\\bar{S}_d$ maximum capacity of battery d, with $d \\in \\mathcal{D}^{sto}$, kWh\n$\\underline{S}_d$ minimum capacity of battery d, with $d \\in \\mathcal{D}^{sto}$, kWh\n$S_d^{init}$ initial state of charge of battery d, with $d \\in \\mathcal{D}^{sto}$, kWh\n$S_d^{end}$ final state of charge of battery d, with $d \\in \\mathcal{D}^{sto}$, kWh\n$J_u^{SU}$ optimal profit of entity u acting individually, €\n$\\gamma_d^{sto}$ unitary cost for usage of battery d, with $d \\in \\mathcal{D}^{sto}$, €/kWh\n$\\gamma^{com}$ unitary fee of the community microgrid operator, €/kWh\n$\\eta_d^{cha}$ charging efficiency of battery d, with $d \\in \\mathcal{D}^{sto}$\n$\\eta_d^{dis}$ discharging efficiency of battery d, with $d \\in \\mathcal{D}^{sto}$\n$\\pi^{peak}$ unitary cost (penalty) for peak power, €/kW\n$\\pi^{res}$ unitary revenue for providing reserve capacity, €/kW\n$\\pi_{d,t}^{she}$ unitary cost of load shedding at time period t, with $d \\in \\mathcal{D}^{she}$, €/kWh\n$\\pi_{d,t}^{ste}$ unitary cost of generating energy at time period t, with $d \\in \\mathcal{D}^{ste}$, €/kWh\n$\\pi_t^{egr}$ unit price of energy exported to the grid at time period t, €/kWh\n$\\pi_t^{igr}$ unit price of energy imported from the grid at time period t, €/kWh\n$\\Delta_T$ duration of a time period, h"},{"evidence_id":"v141-b-g01-e029","location":{"location_id":"src-13c261d954-p02-c2r2__v141-a-M01-clearing","page":2,"printed_page":null,"section":"Nomenclature","anchor_text":"eucomt, + energy exported to the community at time period t by entity u , kWh eugrit, + energy expor","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"Variables\n$\\alpha$ + slack variable to be maximized, €\n$\\alpha_{d,t}^{she}$ [0, 1] fraction of flexible power consumption that is shed at time period t, with $d \\in \\mathcal{D}^{she}$\n$\\alpha_{d,t}^{ste}$ [0, 1] fraction of steerable power generation that is activated at time period t, with $d \\in \\mathcal{D}^{ste}$\n$\\alpha_{d,t}^{cha}$ [0, 1] fraction of the maximum charging power used for battery d at time period t, with $d \\in \\mathcal{D}^{sto}$\n$\\alpha_{d,t}^{dis}$ [0, 1] fraction of the maximum discharging power used for battery d at time period t, with $d \\in \\mathcal{D}^{sto}$\n$e_{u,t}^{com}$ R_+ energy exported to the community at time period t by entity u, kWh\n$e_{u,t}^{gri}$ R_+ energy exported to the grid at time period t by entity u, kWh\n$i_{u,t}^{com}$ R_+ energy imported from the community at time period t by entity u, kWh\n$i_{u,t}^{gri}$ R_+ energy imported from the grid at time period t by entity u, kWh\n$\\bar{p}$ R_+ peak power of the microgrid over the planning horizon T, kW\n$\\bar{p}_u$ R_+ contribution to the peak power of the microgrid assigned to entity u, kW\n$r^{sym}$ R_+ symmetric power reserve provided by the microgrid through all periods of the planning horizon T, kW\n$r_u^{sym}$ R_+ contribution to the symmetric power reserve of the microgrid assigned to entity u, kW\n$r_{u,t}^{inc}$ R_+ upward reserve of power available at time period t and provided by entity u, kW\n$r_{u,t}^{dec}$ R_ downward reserve of power available at time period t and provided by entity u, kW\n$r_{d,t}^{s+}$ R_+ upward reserve of power available at time period t and provided by storage device d, kW\n$r_{d,t}^{s-}$ R_ downward reserve of power available at time period t and provided by storage device d, kW\n$s_{d,t}$ [S̲_d, S̄_d] state of charge of battery d at time period t, with $d \\in \\mathcal{D}^{sto}$, kWh\n$J_u$ R total profit of entity u acting in the community, €\n$J_u^{energy}$ R energy component of the profit of entity u, €\n$J_u^{peak}$ R_ peak power component of the profit of entity u, €\n$J_u^{reserve}$ R_ reserve component of the profit of entity u, €\n$J^*$ R optimal profit of the community microgrid, €\n\nDual Variables, and Corresponding Constraints\n$\\kappa_{d,t}^{s+}/\\kappa_{d,t}^{s-}$ R_+ storage upward/downward reserve, state of charge\n$\\mu_t$ R community energy balance\n$\\pi_{u,t}^{com}$ R entity energy balance\n$\\varphi_t^{inc}/\\varphi_t^{dec}$ R_+ symmetric reserve, upward/downward reserve\n$\\zeta_{d,t}$ R dynamics of battery state of charge\n$\\varphi_{d,t}^{she}/\\varphi_{d,t}^{ste}$ R_+ maximum load shedding/steerable generation\n$\\varphi_{d,t}^{cha}/\\varphi_{d,t}^{dis}$ R_+ maximum storage charging/discharging\n$\\varphi_{d,t}^{socUp}/\\varphi_{d,t}^{socLo}$ R_+ maximum/minimum battery state of charge\n$\\varphi_{u,t}^{eCap}/\\varphi_{u,t}^{iCap}$ R_+ maximum energy export/import to/from the grid\n$\\varphi_t^{peak}$ R_+ community peak power\n$\\varphi_{d,t}^{s+}/\\varphi_{d,t}^{s-}$ R_+ storage upward/downward reserve, power\n$\\xi_d$ R final battery state of charge"},{"evidence_id":"v141-b-g02-E33","location":{"location_id":"src-13c261d954-p08-c1r3__v141-a-M01-clearing","page":8,"printed_page":null,"section":"4.1.1","anchor_text":"component of Ju . On the other hand, the values in the second column, referred to the community, are","equation_id":null,"figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"the excess of generation is sold to the grid (e_{2,1}^gri = 2 kWh) at price π_1^egr = 0.035 €/kWh, which sets the community market price π_{2,1}^com for entity 2. Indeed, the main grid represents the marginal unit, and its bid price defines the local market price for that entity. […] Concerning entity 1, it buys energy from entity 2 at price π_{1,1}^com = 0.055 €/kWh, which includes the market price π_{2,1}^com of entity 2, and the fee γ^com due to the community microgrid operator, collected both on import i_{1,1}^com and export e_{2,1}^com."},{"evidence_id":"v141-b-g03-e07","location":{"location_id":"src-13c261d954-p10-c2r2__v141-a-M01-pricing","page":10,"printed_page":"556","section":"4.1.6","anchor_text":"the low price at which energy is sold to the grid, when they act in se dividually, entities 2 and 3 ","equation_id":"(43)","figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"formula"},"source_text":"Moreover, for two entities both exporting energy to the community, the market prices are equal, as follows from the complementary slackness conditions corresponding to the dual constraints (A.7). Since \\pi_{3,1}^{ste} > \\pi_{2,1}^{ste}, entity 3 is the marginal unit, and defines the price. Indeed, the optimization returns\n\n\\pi_{2,1}^{com} = \\pi_{3,1}^{com} = \\frac{\\pi^{res}}{\\Delta_\\tau} + \\pi_{3,1}^{ste} = 0.225\\,\\text{EUR/kWh}.   (43)"},{"evidence_id":"v141-b-g03-e29","location":{"location_id":"src-13c261d954-p13-c1r2__v141-a-M01-pricing","page":13,"printed_page":"559","section":"Appendix C.1","anchor_text":"The strong duality condition requires the identity, at the optimum, of th function (B.1). Appendix C","equation_id":"(C.1), (C.2)","figure_id":null,"table_id":null,"image_ref":"pages/page-13.png","occurrence_role":"formula"},"source_text":"This appendix shows that identity (25) holds at the optimum of the lower level problem. First, we notice that\n\ne_{u,t}^{com}\\,\\pi_{u,t}^{com} = e_{u,t}^{com}\\left( \\mu_t - \\gamma^{com} \\right).   (C.1)\n\nIf e_{u,t}^{com} = 0, the identity is trivial. If e_{u,t}^{com} > 0, it follows from the complementary slackness condition corresponding to the dual constraint (A.7), implying \\pi_{u,t}^{com} = \\mu_t - \\gamma^{com}. Similarly,\n\ni_{u,t}^{com}\\,\\pi_{u,t}^{com} = i_{u,t}^{com}\\left( \\mu_t + \\gamma^{com} \\right),   (C.2)\n\nwhere the identity is trivial when i_{u,t}^{com} = 0, while it follows from the complementary slackness condition corresponding to the dual constraint (A.8), implying \\pi_{u,t}^{com} = \\mu_t + \\gamma^{com}, when i_{u,t}^{com} > 0."},{"evidence_id":"v141-b-g04-E05","location":{"location_id":"src-13c261d954-p12-c2r3__v141-a-M01-pricing","page":12,"printed_page":"558","section":"Appendix A. Lower level dual constraints","anchor_text":"(A.6) (A.7) (A.8) (A.9) (A.10) (A.11) (A.12) (A.13)","equation_id":"(A.7),(A.8)","figure_id":null,"table_id":null,"image_ref":"pages/page-12.png","occurrence_role":"formula"},"source_text":"The dual constraints of e^{com}_{u,t} \\ge 0 and i^{com}_{u,t} \\ge 0 are respectively\n\\pi^{com}_{u,t} - \\mu_t \\ge -\\gamma^{com}   (A.7)\n-\\pi^{com}_{u,t} + \\mu_t \\ge -\\gamma^{com}   (A.8)"},{"evidence_id":"v141-b-g01-e007","location":{"location_id":"src-13c261d954-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"2. The community microgrid architecture","anchor_text":"operationalplanning stage that optimizes day-ahead decisions with le time periods of T hours, given ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"To achieve the aforementioned benefits, this paper focuses on the operational planning stage that optimizes day-ahead decisions with time periods of $\\Delta_T$ hours, given the grid energy prices, and the consumption and generation forecasts of the entities. An operator manages the community to maximize its social welfare, by optimizing the energy flows and the interactions among the entities and with the public grid. The operator must be contractually bound to the DSO, and its perimeter must be clearly defined. It must also be trusted by, and be contractually bound to, the community entities. The latter pay a fee to the operator for the remuneration of its activity."},{"evidence_id":"v141-b-g01-e022","location":{"location_id":"src-13c261d954-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1.1. Lower level problem","anchor_text":"eugri, t i ugri, t + eucom, t i ucom, t nst ste ste3) T Pd, t + ad, t Pd, t u y, d unst d ste n- at ","equation_id":"(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"$\\sum_{u \\in \\mathcal{U}} \\left( i_{u,t}^{com} - e_{u,t}^{com} \\right) = 0 \\quad \\forall t \\in \\mathcal{T} \\quad [\\mu_t \\in \\mathbb{R}]$  (12)\nConstraint (12) imposes the balance of the energy flows within the community at each time period."},{"evidence_id":"v141-b-g03-e01","location":{"location_id":"src-13c261d954-p08-c1r4__v141-a-M01-pricing","page":8,"printed_page":"554","section":"4.1.1","anchor_text":"com com 1 1,1 = 0.055 €/kWh, which includes the market price 2,1 of entity 2, and the fee com due to","equation_id":"(37)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"This reflects the following relation, which is derived from (C.1) and (C.2) for an entity u with e_{u,t}^{com} > 0, and an entity u' with i_{u',t}^{com} > 0:\n\n\\pi_{u',t}^{com} = \\pi_{u,t}^{com} + 2\\gamma^{com}.   (37)"},{"evidence_id":"v141-b-g03-e23","location":{"location_id":"src-13c261d954-p12-c1r3__v141-a-M01-pricing","page":12,"printed_page":"558","section":"Appendix A","anchor_text":"s + dis s socUp socLo d , T d , T + d, T + d d , T d + chad, T = 0 T d T The dual constraints of euc","equation_id":"(A.7), (A.8)","figure_id":null,"table_id":null,"image_ref":"pages/page-12.png","occurrence_role":"formula"},"source_text":"The dual constraints of e_{u,t}^{com} >= 0 and i_{u,t}^{com} >= 0 are respectively:\n\n\\pi_{u,t}^{com} - \\mu_t \\geq -\\gamma^{com}   (A.7)\n\n-\\pi_{u,t}^{com} + \\mu_t \\geq -\\gamma^{com}   (A.8)"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M01-validation"],"extras":{"decision_anchor":"pricing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e011","quote":"In the proposed bilevel model, the lower level solves the community microgrid market clearing problem, by determining: the executed quantities, the community prices, the community symmetric reserve, and the community peak power, with the aim of maximizing the social welfare of the community."}],[{"evidence_id":"v141-b-g01-e003","quote":"the design of a local market for community microgrids, where the prices are determined through a social welfare maximization approach fulfilling the marginal pricing framework;"}],[{"evidence_id":"v141-b-g03-e29","quote":"If e_{u,t}^{com} > 0, it follows from the complementary slackness condition corresponding to the dual constraint (A.7), implying \\pi_{u,t}^{com} = \\mu_t - \\gamma^{com}."},{"evidence_id":"v141-b-g01-e029","quote":"$e_{u,t}^{com}$ R_+ energy exported to the community at time period t by entity u, kWh"},{"evidence_id":"v141-b-g03-e07","quote":"Moreover, for two entities both exporting energy to the community, the market prices are equal, as follows from the complementary slackness conditions corresponding to the dual constraints (A.7)."}],[{"evidence_id":"v141-b-g03-e29","quote":"where the identity is trivial when i_{u,t}^{com} = 0, while it follows from the complementary slackness condition corresponding to the dual constraint (A.8), implying \\pi_{u,t}^{com} = \\mu_t + \\gamma^{com}, when i_{u,t}^{com} > 0."},{"evidence_id":"v141-b-g01-e029","quote":"$i_{u,t}^{com}$ R_+ energy imported from the community at time period t by entity u, kWh"}],[{"evidence_id":"v141-b-g02-E33","quote":"Concerning entity 1, it buys energy from entity 2 at price π_{1,1}^com = 0.055 €/kWh, which includes the market price π_{2,1}^com of entity 2, and the fee γ^com due to the community microgrid operator, collected both on import i_{1,1}^com and export e_{2,1}^com."}],[{"evidence_id":"v141-b-g01-e025","quote":"Indeed, being $\\pi_{u,t}^{com}$ the dual variable of the energy balance constraint for entity u, in the proposed formulation it represents the market price at which entity u exchanges energy with the community at time t [33]."}],[{"evidence_id":"v141-b-g04-E05","quote":"The dual constraints of e^{com}_{u,t} \\ge 0 and i^{com}_{u,t} \\ge 0 are respectively\n\\pi^{com}_{u,t} - \\mu_t \\ge -\\gamma^{com}   (A.7)\n-\\pi^{com}_{u,t} + \\mu_t \\ge -\\gamma^{com}   (A.8)"},{"evidence_id":"v141-b-g01-e029","quote":"$\\mu_t$ R community energy balance"},{"evidence_id":"v141-b-g01-e028","quote":"$\\gamma^{com}$ unitary fee of the community microgrid operator, €/kWh"}]],"C2_formalization":{"graph_sha256":"f2c467b17cce933be494c009b56c933e2403907292519eb3093caeeac0438f73","applicability":"formalized","reason":"The core local-price relations C003, C004, C005, and C007 are transcribed from source equations (C.1), (C.2), (37), and the dual constraints (A.7)-(A.8). C001, C002, and C006 remain procedural or definitional statements without a forced mathematical expression. Declared variables and parameters are bound to the existing clearing, pricing, execution, and settlement nodes and edges.","bindings":[{"object_id":"v141-c-R005-x-pi_com","node_ids":["pricing.local","clearing.local"],"edge_ids":["v141-c-R005-E001","v141-c-R005-E003"],"rationale":"Community price pi_com is an operational variable in the lower-level clearing, linked from clearing.local to pricing.local (E001) and conditioning energy-trade execution (E003)."},{"object_id":"v141-c-R005-x-e_com","node_ids":["execution.energy_trade","pricing.local"],"edge_ids":["v141-c-R005-E003"],"rationale":"e_com is the executed community export quantity on which the local-price conditional in C003 depends; edge E003 is the conditional-on link."},{"object_id":"v141-c-R005-x-i_com","node_ids":["execution.energy_trade","pricing.local"],"edge_ids":["v141-c-R005-E003"],"rationale":"i_com is the executed community import quantity on which the local-price conditional in C004 depends; edge E003 is the conditional-on link."},{"object_id":"v141-c-R005-x-mu","node_ids":["clearing.local","pricing.local"],"edge_ids":["v141-c-R005-E001"],"rationale":"mu_t is the dual variable of the community energy-balance constraint within clearing.local and enters the local price relation; edge E001 links clearing.local to pricing.local."},{"object_id":"v141-c-R005-theta-gamma_com","node_ids":["pricing.local","settlement.payment"],"edge_ids":["v141-c-R005-E004"],"rationale":"gamma_com is the unitary operator fee that augments or reduces the local price and is settled through settlement.payment (E004)."},{"object_id":"v141-c-R005-C003","node_ids":["pricing.local","execution.energy_trade"],"edge_ids":["v141-c-R005-E003"],"rationale":"C003 formalizes the local-price conditional on a positive community export and the equality of prices for two exporters, matching edge E003 pricing.local -> execution.energy_trade (conditional_on)."},{"object_id":"v141-c-R005-C004","node_ids":["pricing.local","execution.energy_trade"],"edge_ids":["v141-c-R005-E003"],"rationale":"C004 formalizes the local-price conditional on a positive community import, matching edge E003 pricing.local -> execution.energy_trade (conditional_on)."},{"object_id":"v141-c-R005-C005","node_ids":["settlement.payment","pricing.local"],"edge_ids":["v141-c-R005-E004"],"rationale":"C005 formalizes that the buyer's local price includes the operator fee collected on both sides, tied to settlement.payment -> pricing.local (E004)."},{"object_id":"v141-c-R005-C007","node_ids":["pricing.local","clearing.local"],"edge_ids":["v141-c-R005-E001"],"rationale":"C007 gives the lower and upper bounds on each local price from the clearing dual constraints (A.7)-(A.8); edge E001 links clearing.local to pricing.local."}],"revision_requests":[]},"C2_delivery":{"raw_sha256":"291bd63c2fa101ba09cb2a69b4ebd50a1bb3e89d4c5bc4143ad5523f9a1dbbd5","delivery_payload_sha256":"53c6a96d968c3fdeef231ab14607f656bf0999aa97b5e962a52ebd7df37f38cf","changes":[{"path":"theta.0.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"f2c467b17cce933be494c009b56c933e2403907292519eb3093caeeac0438f73","scientific_correctness_verified":false}},"quarantined_references":[]}});
